// 1. OBTENER EL TEXTO DE ENTRADA

let text = $input.item.json.data || 
           $input.item.json.body || 
           $input.item.json.pageContent || 
           $input.item.json;

if (typeof text !== 'string') {
  text = JSON.stringify(text);
}

// 2. RUTINA DE LIMPIEZA DE CONTENIDO

// A. Eliminar encabezado y pie corporativo/académico (específico para evitar borrar el centro)
text = text.replace(/# 🎬 Fictional Entertainment MX[\s\S]*?\*Plataforma de Streaming[^\n]*/gi, '');
text = text.replace(/# 🎬 Fictional Entertainment MX[\s\S]*?\*Fictional Entertainment MX es una empresa ficticia\.\*/gi, '');
text = text.replace(/\n\*Plataforma de Streaming • Microservicios • Cloud Native • Seguridad\*\n\n/gi, '');

// B. Eliminar frases sueltas repetitivas
text = text.replace(/— Fictional Entertainment MX/gi, '');
text = text.replace(/Documento generado con fines académicos/gi, '');

// C. Eliminar imágenes en formato Markdown: ![Descripción](https://link...)
text = text.replace(/!\[.*?\]\(.*?\)/g, '');

// D. Eliminar cualquier etiqueta HTML (<div align="center">, <br>, </div>, etc.)
text = text.replace(/<[^>]+>/g, '');

// E. Eliminar emojis y pictogramas Unicode
text = text.replace(/[\p{Extended_Pictographic}\p{Emoji_Presentation}]/gu, '');

// F. Eliminar líneas divisorias o decorativas (---, ===, ***, !!!)
text = text.replace(/^[!\-*_=]{3,}\s*$/gm, '');

// G. Limpiar espacios en blanco al inicio y al final de cada línea
text = text.split('\n').map(line => line.trim()).join('\n');

// H. Reducir múltiples saltos de línea (3 o más) a un máximo de 2
text = text.replace(/\n{3,}/g, '\n\n');

// I. Limpiar espacios en los extremos globales
text = text.trim();

// DEVOLVER EL FORMATO CORRECTO PARA n8n

return {
  json: {
    pageContent: text
  }
};
